use crate::io::util::write_all_buf::{IdleWriter, WriteAllBuf};
use crate::io::AsyncWrite;

use bytes::Buf;
use pin_project_lite::pin_project;
use std::future::Future;
use std::io;
use std::marker::PhantomPinned;
use std::pin::Pin;
use std::task::{Context, Poll};

pin_project! {
    /// A future to write some of the buffer to an `AsyncWrite`.
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct Write<'a, W: ?Sized> {
        writer: &'a mut W,
        buf: &'a [u8],
        // Make this future `!Unpin` for compatibility with async trait methods.
        #[pin]
        _pin: PhantomPinned,
    }
}

/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write<'a, W>(writer: &'a mut W, buf: &'a [u8]) -> Write<'a, W>
where
    W: AsyncWrite + Unpin + ?Sized,
{
    Write {
        writer,
        buf,
        _pin: PhantomPinned,
    }
}

fn with_writer_session<W, T>(
    writer: &mut W,
    f: impl FnOnce(&mut WriteAllBuf<'_, W, bytes::Bytes>) -> T,
) -> T
where
    W: AsyncWrite + Unpin + ?Sized,
{
    let mut empty = bytes::Bytes::new();
    let mut session = WriteAllBuf::coordinator(writer, &mut empty);
    f(&mut session)
}

fn with_idle_session<T>(f: impl FnOnce(&mut WriteAllBuf<'_, IdleWriter, bytes::Bytes>) -> T) -> T {
    let mut idle = IdleWriter;
    let mut empty = bytes::Bytes::new();
    let mut session = WriteAllBuf::coordinator(&mut idle, &mut empty);
    f(&mut session)
}

pub(super) fn poll_once<W>(
    writer: &mut W,
    buf: &[u8],
    cx: &mut Context<'_>,
) -> Poll<io::Result<usize>>
where
    W: AsyncWrite + Unpin + ?Sized,
{
    with_writer_session(writer, |session| {
        if buf.is_empty() {
            session.poll_single_write(cx, buf)
        } else {
            session.poll_single_write_from_parts(cx, buf, 0, buf.len())
        }
    })
}

pub(super) fn poll_once_pinned<W>(
    writer: Pin<&mut W>,
    buf: &[u8],
    cx: &mut Context<'_>,
) -> Poll<io::Result<usize>>
where
    W: AsyncWrite + ?Sized,
{
    with_idle_session(|session| session.poll_copy_write_window(writer, cx, buf, 0, buf.len()))
}

pub(super) fn poll_all_slice<W>(
    writer: &mut W,
    buf: &mut &[u8],
    cx: &mut Context<'_>,
) -> Poll<io::Result<()>>
where
    W: AsyncWrite + Unpin + ?Sized,
{
    poll_all_slice_pinned(Pin::new(&mut *writer), buf, cx)
}

pub(super) fn poll_all_slice_pinned<W>(
    writer: Pin<&mut W>,
    buf: &mut &[u8],
    cx: &mut Context<'_>,
) -> Poll<io::Result<()>>
where
    W: AsyncWrite + ?Sized,
{
    with_idle_session(|session| {
        let poll = session.poll_write_all_window_pinned(writer, cx, buf);
        let written = session.slice_consumed();
        if written > buf.len() {
            *buf = &buf[buf.len()..];
        } else {
            *buf = &buf[written..];
        }
        poll
    })
}

pub(super) fn poll_buf_chunk<W, B>(
    writer: &mut W,
    buf: &mut B,
    cx: &mut Context<'_>,
) -> Poll<io::Result<usize>>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    let mut session = WriteAllBuf::coordinator(writer, buf);
    session.poll_chunk_write(cx)
}

pub(super) fn poll_int_bytes<W>(
    writer: Pin<&mut W>,
    cx: &mut Context<'_>,
    data: &[u8],
    written: &mut usize,
) -> Poll<io::Result<()>>
where
    W: AsyncWrite + ?Sized,
{
    with_idle_session(|session| {
        session.load_int_scratch(data);
        let poll = session.poll_int_scratch_pinned(writer, cx);
        *written = session.int_consumed();
        poll
    })
}

pub(super) fn poll_one_byte<W>(
    writer: Pin<&mut W>,
    cx: &mut Context<'_>,
    byte: u8,
) -> Poll<io::Result<()>>
where
    W: AsyncWrite + ?Sized,
{
    with_idle_session(|session| session.poll_one_byte_pinned(writer, cx, byte))
}

pub(super) fn flush_buffered<W>(
    writer: Pin<&mut W>,
    buf: &mut Vec<u8>,
    written: &mut usize,
    cx: &mut Context<'_>,
) -> Poll<io::Result<()>>
where
    W: AsyncWrite + ?Sized,
{
    with_idle_session(|session| session.drive_flush_vec(writer, buf, written, cx))
}

pub(super) fn poll_buffered_write<W>(
    writer: Pin<&mut W>,
    buf: &mut Vec<u8>,
    written: &mut usize,
    cx: &mut Context<'_>,
    src: &[u8],
) -> Poll<io::Result<usize>>
where
    W: AsyncWrite + ?Sized,
{
    with_idle_session(|session| session.drive_buffered_write(writer, buf, written, cx, src))
}

pub(super) fn poll_buffered_write_vectored<W>(
    writer: Pin<&mut W>,
    buf: &mut Vec<u8>,
    written: &mut usize,
    cx: &mut Context<'_>,
    bufs: &[io::IoSlice<'_>],
    inner_is_vectored: bool,
) -> Poll<io::Result<usize>>
where
    W: AsyncWrite + ?Sized,
{
    with_idle_session(|session| {
        session.drive_buffered_write_vectored(writer, buf, written, cx, bufs, inner_is_vectored)
    })
}

pub(super) fn poll_writer_flush<W>(writer: &mut W, cx: &mut Context<'_>) -> Poll<io::Result<()>>
where
    W: AsyncWrite + Unpin + ?Sized,
{
    with_writer_session(writer, |session| session.poll_writer_flush(cx))
}

pub(super) fn poll_writer_shutdown<W>(writer: &mut W, cx: &mut Context<'_>) -> Poll<io::Result<()>>
where
    W: AsyncWrite + Unpin + ?Sized,
{
    with_writer_session(writer, |session| session.poll_writer_shutdown(cx))
}

pub(super) fn poll_write_vectored_once<W>(
    writer: &mut W,
    bufs: &[io::IoSlice<'_>],
    cx: &mut Context<'_>,
) -> Poll<io::Result<usize>>
where
    W: AsyncWrite + Unpin + ?Sized,
{
    with_writer_session(writer, |session| session.poll_single_write_vectored(cx, bufs))
}

