fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
    let me = self.project();

    if me.writer.is_write_vectored() {
        const MAX_VECTOR_LEN: usize = 8;
        let mut slices = [io::IoSlice::new(&[]); MAX_VECTOR_LEN];

        while me.buf.has_remaining() {
            let n_slices = me.buf.chunks_vectored(&mut slices);
            if n_slices == 0 {
                let n = ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk())?);
                if n == 0 {
                    return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
                }
                me.buf.advance(n);
                continue;
            }

            let n = ready!(Pin::new(&mut *me.writer)
                .poll_write_vectored(cx, &slices[..n_slices])?);
            if n == 0 {
                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
            }
            me.buf.advance(n);
        }
    } else {
        while me.buf.has_remaining() {
            let n = ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk())?);
            me.buf.advance(n);
            if n == 0 {
                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
            }
        }
    }

    Poll::Ready(Ok(()))
}

